import fs from 'node:fs';

const sets=[
 {privacy:'privacy-policy/index.html',faq:'faq/index.html',booking:'Booking fees, invoices and payment',terms:'/terms-conditions/',privacyHref:'/privacy-policy/',bridge:`<section class="section-band legal-navigation"><div class="wrap"><div class="section-head"><p class="eyebrow">Project rules and privacy</p><h2>One authoritative place for each answer</h2><p class="lead">Preparation questions stay here. Contract terms, payment, delivery, licensing and data protection are maintained in their canonical legal pages so the wording does not drift between documents.</p></div><div class="service-grid"><article class="card"><h3>Fees, booking and project terms</h3><p>The accepted written offer and the Terms &amp; Conditions define fees, booking, rescheduling and the project framework.</p><a class="btn-link" href="/terms-conditions/">Read the Terms &amp; Conditions →</a></article><article class="card"><h3>Privacy and personal data</h3><p>The Privacy Notice explains data processing, storage, access, deletion and cross-domain measurement.</p><a class="btn-link" href="/privacy-policy/">Read the Privacy Notice →</a></article><article class="card"><h3>Delivery and image use</h3><p>Delivery, approvals and permitted image use are defined by the accepted offer together with the contractual terms.</p><a class="btn-link" href="/terms-conditions/">Review delivery and licence terms →</a></article></div></div></section>`},
 {privacy:'hu/adatvedelem/index.html',faq:'hu/gyik/index.html',booking:'Foglalási díj, számlázás és fizetés',terms:'/hu/aszf/',privacyHref:'/hu/adatvedelem/',bridge:`<section class="section-band legal-navigation"><div class="wrap"><div class="section-head"><p class="eyebrow">Projektfeltételek és adatvédelem</p><h2>Minden válasznak egy hiteles helye van</h2><p class="lead">A felkészüléssel kapcsolatos gyakori kérdések itt maradnak. A szerződéses feltételek, fizetés, átadás, licenc és adatkezelés a saját kanonikus jogi oldalán él, így a szöveg nem térhet el dokumentumonként.</p></div><div class="service-grid"><article class="card"><h3>Díjak, foglalás és projektfeltételek</h3><p>Az elfogadott írásos ajánlat és az ÁSZF rögzíti a díjakat, foglalást, átütemezést és a projekt kereteit.</p><a class="btn-link" href="/hu/aszf/">ÁSZF megnyitása →</a></article><article class="card"><h3>Adatvédelem és személyes adatok</h3><p>Az Adatkezelési tájékoztató írja le az adatkezelést, tárolást, hozzáférést, törlést és a domainek közötti mérést.</p><a class="btn-link" href="/hu/adatvedelem/">Adatkezelési tájékoztató →</a></article><article class="card"><h3>Átadás és képfelhasználás</h3><p>Az átadást, jóváhagyást és engedélyezett képfelhasználást az elfogadott ajánlat és a szerződéses feltételek együtt rögzítik.</p><a class="btn-link" href="/hu/aszf/">Átadási és licencfeltételek →</a></article></div></div></section>`},
 {privacy:'de-at/datenschutz/index.html',faq:'de-at/faq/index.html',booking:'Reservierungsentgelt, Rechnung und Zahlung',terms:'/de-at/agb/',privacyHref:'/de-at/datenschutz/',bridge:`<section class="section-band legal-navigation"><div class="wrap"><div class="section-head"><p class="eyebrow">Projektregeln und Datenschutz</p><h2>Für jede Antwort gibt es eine verbindliche Quelle</h2><p class="lead">Fragen zur Vorbereitung bleiben hier. Vertragsbedingungen, Zahlung, Übergabe, Lizenz und Datenschutz werden auf ihren kanonischen Rechtsseiten gepflegt, damit Formulierungen nicht zwischen Dokumenten auseinanderlaufen.</p></div><div class="service-grid"><article class="card"><h3>Honorar, Buchung und Projektbedingungen</h3><p>Das angenommene schriftliche Angebot und die AGB regeln Honorar, Buchung, Verschiebung und den Projektrahmen.</p><a class="btn-link" href="/de-at/agb/">AGB öffnen →</a></article><article class="card"><h3>Datenschutz und personenbezogene Daten</h3><p>Die Datenschutzerklärung beschreibt Verarbeitung, Speicherung, Zugriff, Löschung und domainübergreifende Messung.</p><a class="btn-link" href="/de-at/datenschutz/">Datenschutzerklärung öffnen →</a></article><article class="card"><h3>Übergabe und Bildnutzung</h3><p>Übergabe, Freigaben und zulässige Bildnutzung werden durch das angenommene Angebot und die Vertragsbedingungen definiert.</p><a class="btn-link" href="/de-at/agb/">Übergabe- und Lizenzbedingungen →</a></article></div></div></section>`}
];

function mainRange(html){const a=html.search(/<main\b/i),b=html.search(/<\/main>/i);if(a<0||b<a)throw new Error('main missing');return{start:a,end:b+7}}
function topSections(html){
 const mr=mainRange(html), sub=html.slice(mr.start,mr.end); const tags=/<\/?section\b[^>]*>/gi; let depth=0,start=-1,out=[],m;
 while((m=tags.exec(sub))){if(/^<section\b/i.test(m[0])){if(depth===0)start=m.index;depth++;}else{depth--;if(depth===0)out.push({start:mr.start+start,end:mr.start+tags.lastIndex,html:sub.slice(start,tags.lastIndex)});if(depth<0)throw new Error('section nesting underflow')}}
 return out;
}
function text(s){return s.replace(/<[^>]+>/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim()}
for(const s of sets){
 let ph=fs.readFileSync(s.privacy,'utf8'); const ps=topSections(ph); const match=ps.filter(x=>text(x.html).includes(s.booking)); if(match.length!==1)throw new Error(`${s.privacy}: expected one booking/payment section, found ${match.length}`); ph=ph.slice(0,match[0].start)+ph.slice(match[0].end); if(text(ph).includes(s.booking))throw new Error(`${s.privacy}: booking/payment copy remains`); fs.writeFileSync(s.privacy,ph);
 let fh=fs.readFileSync(s.faq,'utf8'); const fsx=topSections(fh); if(fsx.length<9)throw new Error(`${s.faq}: expected full legacy FAQ structure before simplification`); const cut=fsx[3]; const last=fsx.at(-1); fh=fh.slice(0,cut.start)+s.bridge+fh.slice(last.end); if((topSections(fh).length)!==4)throw new Error(`${s.faq}: expected 4 top-level sections after simplification`); if(!fh.includes(s.terms)||!fh.includes(s.privacyHref))throw new Error(`${s.faq}: canonical legal links missing`); fs.writeFileSync(s.faq,fh);
 console.log(`${s.privacy}: removed commercial terms from privacy notice; ${s.faq}: replaced duplicated legal chapters with canonical navigation.`);
}
